import { writeFileSync } from 'node:fs';

const supabaseUrl = process.env.STAGING_SUPABASE_URL?.trim();
const supabaseAnonKey = process.env.STAGING_SUPABASE_ANON_KEY?.trim();

if (!supabaseUrl || !supabaseAnonKey) {
  throw new Error('STAGING_SUPABASE_URL and STAGING_SUPABASE_ANON_KEY are required');
}

if (supabaseUrl !== 'https://ecxkhihlbrcwpavfoaoq.supabase.co') {
  throw new Error('Refusing to emit runtime config for a non-staging Supabase project');
}

const runtimeConfig = [
  '// Generated by GitHub Actions for the staging Pages deployment.',
  '// Contains only browser-public Supabase configuration. Never add service-role credentials.',
  'window.HACKER_DOJO_CONFIG = {',
  `  supabaseUrl: ${JSON.stringify(supabaseUrl)},`,
  `  supabaseAnonKey: ${JSON.stringify(supabaseAnonKey)}`,
  '};',
  '',
].join('\n');

writeFileSync('runtime-config.js', runtimeConfig, { encoding: 'utf8', mode: 0o600 });

